bool array_insert(int data[], int *length, int capacity, int index, int value) {
    if (index < 0 || index > *length || *length >= capacity)
        return false;
    for (int i = *length; i > index; i--)
        data[i] = data[i - 1];
    data[index] = value;
    (*length)++;
    return true;
}

