int binary_search(const int data[], int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (data[mid] == target)
            return mid;
        if (data[mid] < target)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return -1;
}

